contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that reverts on transferFrom for the second address
        address token = address(new TokenRevertOnSecond());
        address from = address(0x123);
        address to1 = address(0x456);
        address to2 = address(0x789);
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        uint256 value = 100;
        // The reference (forward loop) will call transferFrom(from, to1, value) then transferFrom(from, to2, value)
        // The second call reverts, so the whole transaction reverts.
        // The buggy (reverse loop) will call transferFrom(from, to2, value) first — reverting — but wait, the buggy calls tos[i-1] for i=2 => to2 first, then i=1 => to1
        // Actually reverse order: first i=2 -> tos[1]=to2, which reverts, so also reverts? Hmm, we need a case where the reverse loop does NOT revert while forward does.
        // Let's make the token revert on the FIRST address (to1) but succeed on the second (to2). Then forward: call to1 (revert) -> full revert. Reverse: call to2 (succeed), then call to1 (revert) -> still reverts at the end, but the first call (to2) already succeeded, partially modifying state (e.g., token balances). The reference will have NO state change, the buggy will have to2's balance increased.
        // So we need a token that records who was called and reverts on the first address.
        TokenRevertOnAddress t = new TokenRevertOnAddress();
        t.setRevertAddress(to1);
        t.mint(from, 1000);
        vm.prank(from);
        t.approve(token, 1000);
        // Now call c.transfer(from, token, tos, 100)
        // We'll catch the revert boolean
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, token, tos, 100));
        // Reference (forward): reverts, so ok == false
        // Buggy (reverse): first calls to2 (no revert), then to1 (revert), but the outer call reverts? Actually the require(_s) on to1 will revert the whole call, so ok == false as well. But there is a state difference: the token's balance of to2 increased for buggy, not for reference.
        // So we need to assert on the token balance of to2.
        uint256 balanceTo2 = t.balanceOf(to2);
        // In the reference, balanceTo2 == 0; in the buggy, balanceTo2 == 100.
        assertTrue(balanceTo2 == 0, "Reference: to2 should have 0 balance after revert; buggy would have 100");
    }
}

contract TokenRevertOnAddress {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    address private revertAddr;
    function setRevertAddress(address a) external { revertAddr = a; }
    function mint(address to, uint256 amount) external { _balances[to] += amount; }
    function approve(address spender, uint256 amount) external { _allowances[msg.sender][spender] = amount; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (to == revertAddr) revert("revert");
        require(_allowances[from][msg.sender] >= amount);
        _allowances[from][msg.sender] -= amount;
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }
    function balanceOf(address account) external view returns (uint256) { return _balances[account]; }
}

