contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that reverts on second transferFrom call
        Token token = new Token();
        address[] memory tos = new address[](2);
        tos[0] = address(token);
        tos[1] = address(token);

        bool ok;
        try c.transfer(address(this), address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: forward loop reverts (ok == false)
        // Bug: reverse loop partially succeeds (ok == true)
        assertTrue(ok == false, "Reference should revert");
    }
}

contract Token {
    uint256 public callCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        if (callCount == 2) {
            revert("Second call fails");
        }
        return true;
    }
}

